using Clock=chrono::steady_clock;
static int64_t nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
static string lower(string s){for(char &c:s)if(c>='A'&&c<='Z')c+=32;return s;}
static string trim(string s){size_t a=0,b=s.size();while(a<b&&(s[a]==' '||s[a]=='\t'))a++;while(b>a&&(s[b-1]==' '||s[b-1]=='\t'))b--;return s.substr(a,b-a);}
static bool number(const string&s,uint64_t &n){if(s.empty())return false;n=0;for(unsigned char c:s){if(c<'0'||c>'9'||n>(UINT64_MAX-(c-'0'))/10)return false;n=n*10+c-'0';}return true;}
static bool tokenchar(unsigned char c){return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||strchr("!#$%&'*+-.^_`|~",c);}
static bool address(const string&s,sockaddr_in &a){auto p=s.rfind(':');if(p==string::npos)return false;uint64_t n;if(!number(s.substr(p+1),n)||n==0||n>65535)return false;memset(&a,0,sizeof(a));a.sin_family=AF_INET;a.sin_port=htons(n);return inet_pton(AF_INET,s.substr(0,p).c_str(),&a.sin_addr)==1;}
struct Config{sockaddr_in listen{},origin{},auth{};string root;int maxconn,headbytes,headms,idlems,writems,maxreq,depth,authms;} cfg;
static bool config(const char*path){ifstream f(path);if(!f)return false;unordered_map<string,string> m;string s;while(getline(f,s)){if(!s.empty()&&s.back()=='\r')s.pop_back();s=trim(s);if(s.empty()||s[0]=='#')continue;auto p=s.find('=');if(p==string::npos)return false;string k=trim(s.substr(0,p)),v=trim(s.substr(p+1));if(k.empty()||!m.emplace(k,v).second)return false;}const vector<string> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","origin_address","auth_address","auth_timeout_ms"};if(m.size()!=keys.size())return false;for(auto&k:keys)if(!m.count(k))return false;if(!address(m["listen"],cfg.listen)||!address(m["origin_address"],cfg.origin)||!address(m["auth_address"],cfg.auth))return false;cfg.root=m["root"];struct stat st{};if(cfg.root.empty()||cfg.root[0]!='/'||stat(cfg.root.c_str(),&st)||!S_ISDIR(st.st_mode))return false;auto get=[&](const char*k,int&out){uint64_t n;if(!number(m[k],n)||!n||n>INT_MAX)return false;out=(int)n;return true;};return get("max_connections",cfg.maxconn)&&get("header_bytes",cfg.headbytes)&&get("header_timeout_ms",cfg.headms)&&get("idle_timeout_ms",cfg.idlems)&&get("write_timeout_ms",cfg.writems)&&get("max_requests",cfg.maxreq)&&get("pipeline_depth",cfg.depth)&&get("auth_timeout_ms",cfg.authms);}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned c=(unsigned char)s[i++];if(c<128)continue;int n;unsigned x,min;if(c>=0xc2&&c<=0xdf){n=1;x=c&31;min=128;}else if(c>=0xe0&&c<=0xef){n=2;x=c&15;min=2048;}else if(c>=0xf0&&c<=0xf4){n=3;x=c&7;min=65536;}else return false;if(i+n>s.size())return false;while(n--){unsigned b=(unsigned char)s[i++];if((b&0xc0)!=0x80)return false;x=(x<<6)|(b&63);}if(x<min||x>0x10ffff||(x>=0xd800&&x<=0xdfff))return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static int decode(const string&target,string&path){if(target.empty()||target[0]!='/'||target.find('#')!=string::npos)return 400;size_t end=target.find('?');if(end==string::npos)end=target.size();for(size_t i=0;i<end;i++){unsigned char c=target[i];if(c=='%'){if(i+2>=end)return 400;int a=hex(target[i+1]),b=hex(target[i+2]);if(a<0||b<0)return 400;c=(a<<4)|b;i+=2;}if(c==0||c=='\\'||c<32||c==127)return 400;path.push_back(c);}if(!utf8(path))return 400;size_t p=0;while(p<path.size()){while(p<path.size()&&path[p]=='/')p++;size_t q=path.find('/',p);if(q==string::npos)q=path.size();if(path.substr(p,q-p)=="..")return 403;p=q;}return 0;}
struct Request{string method,target,version,host,auth,path;bool close=false,head=false,auth_present=false;};
static int parse_request(const string &s,Request&r){size_t end=s.find("\r\n");if(end==string::npos)return 400;string line=s.substr(0,end);auto a=line.find(' ');if(a==string::npos||a==0)return 400;auto b=line.find(' ',a+1);if(b==string::npos||b==a+1||line.find(' ',b+1)!=string::npos)return 400;r.method=line.substr(0,a);for(unsigned char c:r.method)if(!tokenchar(c))return 400;r.target=line.substr(a+1,b-a-1);r.version=line.substr(b+1);if(r.version!="HTTP/1.1"&&r.version!="HTTP/1.0")return 400;r.close=r.version=="HTTP/1.0";for(unsigned char c:r.target)if(c<=32||c==127)return 400;bool gateway=r.target.compare(0,9,"/gateway/")==0;int patherr=decode(r.target,r.path);if(patherr&&!(gateway&&patherr==403))return patherr;int hosts=0,auths=0,cls=0;bool te=false,conclose=false;uint64_t cl=0;size_t p=end+2;while(p<s.size()){auto q=s.find("\r\n",p);if(q==string::npos)return 400;if(q==p){p=q+2;break;}if(s[p]==' '||s[p]=='\t')return 400;auto colon=s.find(':',p);if(colon==string::npos||colon>=q||colon==p)return 400;string name=s.substr(p,colon-p);for(unsigned char c:name)if(!tokenchar(c))return 400;name=lower(name);string val=s.substr(colon+1,q-colon-1);for(unsigned char c:val)if(c==0||c=='\r'||c=='\n'||(c<32&&c!='\t')||c==127)return 400;val=trim(val);if(name=="host"){hosts++;r.host=val;}else if(name=="authorization"){auths++;r.auth=val;r.auth_present=true;}else if(name=="content-length"){cls++;if(!number(val,cl))return 400;}else if(name=="transfer-encoding")te=true;else if(name=="connection"){size_t x=0;while(x<=val.size()){size_t y=val.find(',',x);if(y==string::npos)y=val.size();if(lower(trim(val.substr(x,y-x)))=="close")conclose=true;if(y==val.size())break;x=y+1;}}p=q+2;}if(p!=s.size()||cls>1||te||cl!=0||auths>1)return 400;if(conclose)r.close=true;if(gateway&&(hosts!=1||r.host.empty()))return 400;if(r.method!="GET"&&r.method!="HEAD")return 405;r.head=r.method=="HEAD";return 0;}
static const char* reason(int s){switch(s){case 200:return "OK";case 301:return "Moved Permanently";case 400:return "Bad Request";case 401:return "Unauthorized";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 431:return "Request Header Fields Too Large";case 500:return "Internal Server Error";case 502:return "Bad Gateway";case 503:return "Service Unavailable";default:return "Response";}}
struct Conn{int fd=-1,up=-1,file=-1;enum State{READ,AUTH,ORIGIN,WRITE} state=READ;string input,output,upout,upin;size_t outpos=0,uppos=0;uint64_t remain=0,upremain=0;off_t fileoff=0;bool close=false,head=false,upconnected=false,upheader=false,streaming=false;int count=0;int64_t deadline=0,first=0;Request req;};
static int ep=-1,rootfd=-1;static unordered_map<int,unique_ptr<Conn>> clients;static unordered_map<int,Conn*> upstreams;static vector<uint32_t> generation;
static void interest(int fd,uint32_t ev,bool add=false){if((size_t)fd>=generation.size())generation.resize((size_t)fd+1);if(add)++generation[fd];epoll_event e{};e.events=ev;e.data.u64=((uint64_t)generation[fd]<<32)|(uint32_t)fd;epoll_ctl(ep,add?EPOLL_CTL_ADD:EPOLL_CTL_MOD,fd,&e);}
static void closeup(Conn*c){if(c->up>=0){epoll_ctl(ep,EPOLL_CTL_DEL,c->up,nullptr);upstreams.erase(c->up);close(c->up);c->up=-1;}c->upout.clear();c->upin.clear();}
static void destroy(Conn*c){int fd=c->fd;closeup(c);if(c->file>=0)close(c->file);epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);close(fd);clients.erase(fd);}
static void respond(Conn*c,int status,uint64_t len,const string&extra="",const string&body="",const string&reasonstr=""){c->state=Conn::WRITE;c->output="HTTP/1.1 "+to_string(status)+" "+(reasonstr.empty()?reason(status):reasonstr)+"\r\nContent-Length: "+to_string(len)+"\r\n"+extra+"Connection: "+(c->close?"close":"keep-alive")+"\r\n\r\n";if(!c->head)c->output+=body;c->outpos=0;c->deadline=nowms()+cfg.writems;interest(c->fd,EPOLLOUT|EPOLLRDHUP);}
static void error(Conn*c,int status,bool force=false){if(force)c->close=true;if(c->file>=0){close(c->file);c->file=-1;}c->remain=0;respond(c,status,0);}
static int openfile(const string&path,int &fd,uint64_t &size){int d=dup(rootfd);if(d<0)return 500;size_t p=0;vector<string> parts;while(p<path.size()){while(p<path.size()&&path[p]=='/')p++;size_t q=path.find('/',p);if(q==string::npos)q=path.size();if(q>p&&path.substr(p,q-p)!=".")parts.push_back(path.substr(p,q-p));p=q;}if(parts.empty()){close(d);return 403;}for(size_t i=0;i<parts.size();i++){int x=openat(d,parts[i].c_str(),O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK|(i+1<parts.size()?O_DIRECTORY:0));int e=errno;close(d);if(x<0){if(e==ELOOP||e==EACCES||e==EPERM)return 403;if(e==ENOTDIR){return 403;}return e==ENOENT?404:403;}d=x;struct stat st{};if(fstat(d,&st)){close(d);return 403;}if(i+1==parts.size()){if(!S_ISREG(st.st_mode)||(!path.empty()&&path.back()=='/')){close(d);return 403;}fd=d;size=st.st_size;return 200;}}close(d);return 404;}
static bool startup(Conn*c,bool auth){int fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0)return false;sockaddr_in &addr=auth?cfg.auth:cfg.origin;int r=connect(fd,(sockaddr*)&addr,sizeof(addr));if(r<0&&errno!=EINPROGRESS){close(fd);return false;}c->up=fd;c->upconnected=(r==0);c->uppos=0;c->upheader=false;c->upin.clear();if(auth){c->state=Conn::AUTH;c->upout="GET /authorize HTTP/1.1\r\nHost: "+c->req.host+"\r\nX-Original-URI: "+c->req.target+"\r\n";if(c->req.auth_present)c->upout+="Authorization: "+c->req.auth+"\r\n";c->upout+="Content-Length: 0\r\nConnection: close\r\n\r\n";c->deadline=nowms()+cfg.authms;}else{c->state=Conn::ORIGIN;c->upout=c->req.method+" "+c->req.target.substr(8)+" HTTP/1.1\r\nHost: "+c->req.host+"\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";c->deadline=nowms()+cfg.writems;}upstreams[fd]=c;interest(fd,EPOLLOUT|EPOLLRDHUP,true);interest(c->fd,EPOLLRDHUP);return true;}
static void process(Conn*c){if(c->state!=Conn::READ)return;size_t e=c->input.find("\r\n\r\n");size_t scan=e==string::npos?c->input.size():e+4;for(size_t i=0;i<scan;i++)if(c->input[i]=='\0'||(c->input[i]=='\n'&&(i==0||c->input[i-1]!='\r'))||(c->input[i]=='\r'&&i+1<scan&&c->input[i+1]!='\n')){c->count++;c->head=false;error(c,400,true);return;}if(e==string::npos){if(c->input.size()>=size_t(cfg.headbytes)){c->count++;c->head=false;error(c,431,true);}return;}size_t n=e+4;if(n>size_t(cfg.headbytes)){c->count++;c->head=false;error(c,431,true);return;}string h=c->input.substr(0,n);int64_t readat=c->first;c->input.erase(0,n);c->first=c->input.empty()?0:readat;c->req=Request{};int status=parse_request(h,c->req);c->count++;c->close=c->req.close||c->count>=cfg.maxreq;c->head=c->req.head;if(status){error(c,status,status!=405);return;}if(c->req.target.compare(0,9,"/gateway/")==0){if(!startup(c,true))error(c,503);return;}uint64_t size=0;int fd=-1;status=openfile(c->req.path,fd,size);if(status!=200){error(c,status);return;}if(c->head||size==0){close(fd);respond(c,200,size,"Content-Type: application/octet-stream\r\n");return;}c->file=fd;c->remain=size;c->fileoff=0;respond(c,200,size,"Content-Type: application/octet-stream\r\n");}
struct UpHeader{int status=0;uint64_t len=0;bool haslen=false;string reason,extra;};
static bool upheader(const string&s,UpHeader&h){size_t q=s.find("\r\n");if(q==string::npos)return false;string line=s.substr(0,q);if(line.size()<12||(line.compare(0,9,"HTTP/1.1 ")&&line.compare(0,9,"HTTP/1.0 "))||line[9]<'1'||line[9]>'9'||line[10]<'0'||line[10]>'9'||line[11]<'0'||line[11]>'9'||(line.size()>12&&line[12]!=' '))return false;h.status=(line[9]-'0')*100+(line[10]-'0')*10+line[11]-'0';if(line.size()>13)h.reason=line.substr(13);for(unsigned char x:h.reason)if(x<32||x==127)return false;vector<pair<string,string>> fields;unordered_set<string> skip={"connection","content-length","transfer-encoding","keep-alive","proxy-authenticate","proxy-authorization","te","trailer","upgrade"};size_t p=q+2;while(p<s.size()){q=s.find("\r\n",p);if(q==string::npos)return false;if(q==p)break;size_t col=s.find(':',p);if(col==string::npos||col==p||col>=q)return false;string name=s.substr(p,col-p);for(unsigned char x:name)if(!tokenchar(x))return false;string key=lower(name),v=trim(s.substr(col+1,q-col-1));for(unsigned char x:v)if(x==0||x=='\r'||x=='\n'||(x<32&&x!='\t')||x==127)return false;if(key=="content-length"){if(h.haslen||!number(v,h.len))return false;h.haslen=true;}if(key=="transfer-encoding")return false;if(key=="connection"){size_t a=0;while(a<=v.size()){size_t b=v.find(',',a);if(b==string::npos)b=v.size();skip.insert(lower(trim(v.substr(a,b-a))));if(b==v.size())break;a=b+1;}}fields.emplace_back(name,v);p=q+2;}for(auto &f:fields)if(!skip.count(lower(f.first)))h.extra+=f.first+": "+f.second+"\r\n";return true;}
static void upstream_event(Conn*c,uint32_t ev){if(c->up<0)return;int fd=c->up;bool auth=c->state==Conn::AUTH;if(ev&EPOLLOUT){if(!c->upconnected){int er=0;socklen_t n=sizeof(er);if(getsockopt(fd,SOL_SOCKET,SO_ERROR,&er,&n)||er){closeup(c);error(c,auth?503:502);return;}c->upconnected=true;}while(c->uppos<c->upout.size()){ssize_t n=send(fd,c->upout.data()+c->uppos,c->upout.size()-c->uppos,MSG_NOSIGNAL);if(n>0)c->uppos+=n;else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;else{closeup(c);error(c,auth?503:502);return;}}if(c->uppos==c->upout.size())interest(fd,EPOLLIN|EPOLLRDHUP);}
 if(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP|EPOLLERR)){string &in=auth?c->upin:c->output;char buf[16384];bool eof=false;size_t total=0;for(;;){ssize_t n=recv(fd,buf,sizeof(buf),0);if(n>0){in.append(buf,n);total+=n;if(!auth)c->deadline=nowms()+cfg.writems;if(in.size()>134217728){closeup(c);error(c,auth?503:502);return;}if(!c->upheader){size_t p=in.find("\r\n\r\n");if(p!=string::npos){if(auth)break;UpHeader h;if(upheader(in.substr(0,p+4),h)&&h.haslen&&h.len<=1048576){in.reserve(p+4+(size_t)h.len+1024);c->upheader=true;}}else if(in.size()>65536){closeup(c);error(c,auth?503:502);return;}}if(total>=262144)break;}else if(n==0){eof=true;break;}else if(errno==EINTR)continue;else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else{eof=true;break;}}size_t end=in.find("\r\n\r\n");if(end==string::npos){if(eof||in.size()>65536){closeup(c);error(c,auth?503:502);}return;}UpHeader h;if(!upheader(in.substr(0,end+4),h)){closeup(c);error(c,auth?503:502);return;}if(auth){int status=h.status;string extra=h.extra;closeup(c);if(status>=200&&status<300){if(!startup(c,false))error(c,502);}else if(status==401||status==403)respond(c,status,0,extra);else error(c,503);return;}if(!h.haslen||h.len>134217728){closeup(c);error(c,502);return;}size_t have=in.size()-(end+4);if(c->head){int status=h.status;uint64_t len=h.len;string extra=h.extra,rs=h.reason;closeup(c);respond(c,status,len,extra,"",rs);return;}if(have>=h.len){in.resize(end+4+(size_t)h.len);string hdr="HTTP/1.1 "+to_string(h.status)+" "+(h.reason.empty()?reason(h.status):h.reason)+"\r\nContent-Length: "+to_string(h.len)+"\r\n"+h.extra+"Connection: "+(c->close?"close":"keep-alive")+"\r\n\r\n";in.replace(0,end+4,hdr);closeup(c);c->state=Conn::WRITE;c->outpos=0;c->deadline=nowms()+cfg.writems;interest(c->fd,EPOLLOUT|EPOLLRDHUP);return;}if(eof){closeup(c);error(c,502);return;}}
}
static void client_event(Conn*c,uint32_t ev){if(c->state==Conn::READ){if(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP|EPOLLERR)){char buf[8192];for(;;){size_t cap=(size_t)cfg.headbytes;if(c->input.size()>=cap){process(c);break;}size_t want=min(sizeof(buf),cap-c->input.size());ssize_t n=recv(c->fd,buf,want,0);if(n>0){if(c->input.empty())c->first=nowms();c->input.append(buf,n);process(c);if(c->state!=Conn::READ)break;}else if(n==0){destroy(c);return;}else if(errno==EINTR)continue;else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else{destroy(c);return;}}}return;}if(c->state==Conn::WRITE&&(ev&(EPOLLOUT|EPOLLHUP|EPOLLERR))){for(;;){if(c->outpos<c->output.size()){ssize_t n=send(c->fd,c->output.data()+c->outpos,c->output.size()-c->outpos,MSG_NOSIGNAL);if(n>0){c->outpos+=n;c->deadline=nowms()+cfg.writems;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;destroy(c);return;}if(c->file>=0&&c->remain){size_t amount=(size_t)min<uint64_t>(c->remain,1048576);ssize_t n=sendfile(c->fd,c->file,&c->fileoff,amount);if(n>0){c->remain-=n;c->deadline=nowms()+cfg.writems;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;destroy(c);return;}if(c->file>=0){close(c->file);c->file=-1;}if(c->close){destroy(c);return;}c->state=Conn::READ;c->output.clear();c->deadline=nowms()+cfg.idlems;interest(c->fd,EPOLLIN|EPOLLRDHUP);process(c);return;}}}
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config"||!config(argv[2]))return 1;signal(SIGPIPE,SIG_IGN);rootfd=open(cfg.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(rootfd<0)return 1;int ls=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(ls<0)return 1;int one=1;setsockopt(ls,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(ls,(sockaddr*)&cfg.listen,sizeof(cfg.listen))||listen(ls,4096))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;interest(ls,EPOLLIN,true);epoll_event events[256];int64_t last=nowms();for(;;){int n=epoll_wait(ep,events,256,50);if(n<0){if(errno==EINTR)continue;break;}for(int i=0;i<n;i++){int fd=(uint32_t)events[i].data.u64;uint32_t ev=events[i].events;if(fd<0||(size_t)fd>=generation.size()||generation[fd]!=(uint32_t)(events[i].data.u64>>32))continue;if(fd==ls){for(;;){int x=accept4(ls,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(x<0){if(errno==EINTR)continue;break;}if((int)clients.size()>=cfg.maxconn){close(x);continue;}auto c=make_unique<Conn>();c->fd=x;c->deadline=nowms()+cfg.idlems;clients[x]=move(c);interest(x,EPOLLIN|EPOLLRDHUP,true);}continue;}auto u=upstreams.find(fd);if(u!=upstreams.end()){upstream_event(u->second,ev);continue;}auto it=clients.find(fd);if(it!=clients.end())client_event(it->second.get(),ev);}int64_t t=nowms();if(t-last>=25){last=t;vector<int> expired;for(auto &kv:clients){Conn*c=kv.second.get();if(c->state==Conn::READ){if((c->first&&t>=c->first+cfg.headms)||(!c->first&&t>=c->deadline))expired.push_back(kv.first);}else if(t>=c->deadline)expired.push_back(kv.first);}for(int fd:expired){auto it=clients.find(fd);if(it==clients.end())continue;Conn*c=it->second.get();if(c->state==Conn::AUTH||c->state==Conn::ORIGIN){int status=c->state==Conn::AUTH?503:502;closeup(c);error(c,status);}else destroy(c);}}}return 1;}
